// Guardrail Ebene 2: gültige Kundenkennung, gültige paket_id, die zu diesem Auftrag gehört. Die Kundenkennung setzt der Hauptworkflow fest.
// Warum test_fehler: nur für Tests, 'foto' erzwingt den Weg ohne Pixabay-Foto, 'render' lässt Gotenberg ausfallen, 'layout4' schaltet Layout 4 für diesen Lauf ein, 'l4fehler' schaltet es ein und lässt dessen Prüfschritt ausfallen. Der Hauptworkflow übergibt das Feld nie.
const j = $input.first().json;
const kuerzel = String(j.kuerzel ?? '').trim().toLowerCase();
const paketId = String(j.paket_id ?? '').trim();
const trace = String(j.trace_id ?? '').trim().slice(0, 60) || 'ohne_trace_id';
const t = String(j.test_fehler ?? '').trim();
const test = (t === 'foto' || t === 'render' || t === 'layout4' || t === 'l4fehler') ? t : '';
let fehler = '';
if (!/^[a-z0-9-]{2,40}$/.test(kuerzel)) fehler = 'FEHLER: ungültige Kundenkennung, keine Bilder erstellt.';
else if (!/^paket-[A-Za-z0-9_-]{3,100}$/.test(paketId)) fehler = 'FEHLER: paket_id fehlt oder ist ungültig, keine Bilder erstellt. Rufe zuerst Text_schreiben auf und nutze die paket_id aus dessen Antwort.';
else if (trace !== 'ohne_trace_id' && !paketId.startsWith('paket-' + trace + '-')) fehler = 'FEHLER: Diese paket_id gehört nicht zu diesem Auftrag, keine Bilder erstellt.';
return [{ json: { kuerzel: kuerzel, paket_id: paketId, trace_id: trace, test_fehler: test, eingabe_ok: fehler === '', fehler_text: fehler } }];

// Zweck (Werkzeug 4, v02 B2a): Paket und Kundenprofil zusammenführen, Marke (Farben, Schriften, Logo, Layouts) in der Feldform von Projekt 1 festlegen; fehlt etwas, endet der Lauf mit NICHT_GEFUNDEN oder FEHLER.
// Herkunft: "Branding-Variante wählen" aus Projekt 1 (branding_pack ganz, Layout je Postform), dazu die K2-Prüfungen. Layout 4 hängt am Schalter LAYOUT4_AN.
// SCHALTER Layout 4 (Plan Fassung 3): seit 19.11.2026 an (true, nach grüner Probe und Kennzeichnungstest, 19.11.2026). false schaltet es ab, dann baut der Rückfall die Layouts 1 bis 3. Nur Instagram-Karussell. test_fehler layout4 oder l4fehler ist nur für Tests (l4fehler lässt den Prüfschritt von Layout 4 ausfallen).
const LAYOUT4_AN = true;
const e = $('Eingabe prüfen [Code]').first().json;
const pRow = $('Paket lesen [Supabase]').first().json || {};
const kunde = $input.first().json || {};
const stopp = t => [{ json: { bereit: false, fehler_text: t } }];
if (!pRow.paket_id) return stopp('NICHT_GEFUNDEN: Für diese paket_id liegt kein Paket vor, keine Bilder erstellt.');
if (pRow.paket_id !== e.paket_id || pRow.kuerzel !== e.kuerzel) return stopp('FEHLER: Das Paket gehört nicht zu diesem Kunden, keine Bilder erstellt.');
if (!kunde.kuerzel || kunde.kuerzel !== e.kuerzel) return stopp('NICHT_GEFUNDEN: Für diesen Kunden gibt es kein aktives Branding, keine Bilder erstellt.');
let paket = pRow.paket;
if (typeof paket === 'string') { try { paket = JSON.parse(paket); } catch (x) { return stopp('FEHLER: Das gespeicherte Paket ist nicht lesbar, keine Bilder erstellt.'); } }
if (!paket || typeof paket !== 'object' || Array.isArray(paket)) return stopp('FEHLER: Das gespeicherte Paket ist nicht lesbar, keine Bilder erstellt.');
// Links gehören nicht in ein Bild (Instagram verlinkt im Beitrag nicht), wie in Paket prüfen aus Projekt 1.
const ohneLink = s => String(s || '').replace(/(https?:\/\/|www\.)\S+/gi, '').replace(/[ \t]{2,}/g, ' ').trim();
const folien = (Array.isArray(paket.slides) ? paket.slides : []).map(f => (f && typeof f === 'object') ? { ...f, heading: ohneLink(f.heading), text: ohneLink(f.text) } : f);
if (folien.length < 5 || folien.length > 8 || folien.some(f => !f || typeof f.heading !== 'string' || typeof f.text !== 'string' || (!f.heading.trim() && !f.text.trim()))) return stopp('FEHLER: Das Paket hat keine gültigen Folien (5 bis 8 mit Überschrift und Text), keine Bilder erstellt.');
paket = { ...paket, slides: folien };
// Platzhalter aus dem Kundenprofil, greift nur, wenn branding_pack leer ist.
const farbe = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const standard = { version: 1, status: 'platzhalter', markenname: kunde.name || 'Kunde',
  logo: { modus: 'datei', pfad: kunde.logo_url || '', text: kunde.name || '' },
  schriften: { titel: kunde.schrift_titel || 'DejaVu Sans', text: kunde.schrift_text || 'DejaVu Sans' },
  farben: { primaer: farbe(kunde.farbe_primaer, '#15774E'), sekundaer: farbe(kunde.farbe_sekundaer, '#515F56'), akzent: farbe(kunde.farbe_akzent, '#22A26F'), hintergrund: farbe(kunde.farbe_hintergrund, '#F4FBF7'), text: farbe(kunde.farbe_text, '#111C16') },
  postformen: ['hybrid_personen', 'thema', 'ablauf'],
  layouts: { instagram: { karussell: [{ id: 'instagram_karussell_1', stil: 'hybrid_personen', postform: 'hybrid_personen' }, { id: 'instagram_karussell_2', stil: 'thema', postform: 'thema' }, { id: 'instagram_karussell_3', stil: 'ablauf', postform: 'ablauf' }], einzelpost: [{ id: 'instagram_einzelpost_1', stil: 'hybrid_personen', postform: 'hybrid_personen' }, { id: 'instagram_einzelpost_2', stil: 'thema', postform: 'thema' }, { id: 'instagram_einzelpost_3', stil: 'ablauf', postform: 'ablauf' }] },
    linkedin: { karussell: [{ id: 'linkedin_karussell_1', stil: 'hybrid_personen', postform: 'hybrid_personen' }, { id: 'linkedin_karussell_2', stil: 'thema', postform: 'thema' }, { id: 'linkedin_karussell_3', stil: 'ablauf', postform: 'ablauf' }], einzelpost: [{ id: 'linkedin_einzelpost_1', stil: 'hybrid_personen', postform: 'hybrid_personen' }, { id: 'linkedin_einzelpost_2', stil: 'thema', postform: 'thema' }, { id: 'linkedin_einzelpost_3', stil: 'ablauf', postform: 'ablauf' }] } } };
let b = kunde.branding_pack;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (x) { return stopp('FEHLER: Das Branding des Kunden ist nicht lesbar, keine Bilder erstellt.'); } }
if (b == null) b = standard;
if (typeof b !== 'object' || Array.isArray(b)) return stopp('FEHLER: Das Branding des Kunden ist kein JSON-Objekt, keine Bilder erstellt.');
b = { ...standard, ...b, logo: { ...standard.logo, ...b.logo }, schriften: { ...standard.schriften, ...b.schriften }, farben: { ...standard.farben, ...b.farben } };
const cust = { ...kunde, name: String(b.markenname || kunde.name || 'Kunde').slice(0, 60) };
for (const [key, value] of Object.entries(b.farben)) {
  if (!/^#[0-9a-fA-F]{6}$/.test(value)) return stopp('FEHLER: Ungültige Branding-Farbe ' + key + ', keine Bilder erstellt.');
  cust['farbe_' + key] = value;
}
cust.schrift_titel = String(b.schriften.titel || 'DejaVu Sans');
cust.schrift_text = String(b.schriften.text || 'DejaVu Sans');
// Pfad des Logos im Speicher (Bucket k1-medien), nur ein sicherer relativer Pfad.
const logoPfad = String(b.logo.pfad || kunde.logo_url || '');
cust.logo_url = /^[A-Za-z0-9][A-Za-z0-9_\/.-]{0,120}$/.test(logoPfad) && !logoPfad.includes('..') ? logoPfad : '';
// Ablauf-Schritte: K2-Pakete tragen keine. Eine Ablauf-Folie würde die Folienzahl ändern, der Einreichen-Sub prüft aber folien.length === slides.length, deshalb bleibt process_steps hier null (in Projekt 1 anders, dort gibt es diese Prüfung nicht).
const schritte = null;
// Postform: Ablauf, wenn Schritte da sind, sonst die des Pakets; K2-Pakete tragen keine, dann stabil aus der paket_id (wie bisher in K2).
let hash = 0; for (const ch of String(e.paket_id)) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
const postform = schritte ? 'ablauf' : (paket.postform || ['hybrid_personen', 'thema', 'ablauf'][hash % 3]);
const varianten = {};
for (const pf of ['instagram', 'linkedin']) {
  varianten[pf] = {};
  for (const fm of ['karussell', 'einzelpost']) {
    const liste = b.layouts && b.layouts[pf] && b.layouts[pf][fm];
    if (!Array.isArray(liste) || liste.length < 3 || liste.length > 5) return stopp('FEHLER: Das Branding hat keine 3 bis 5 Layouts für ' + pf + ' ' + fm + ', keine Bilder erstellt.');
    const v = liste.find(x => x && x.postform === postform) || liste[0];
    if (!v || !v.id || !['hybrid_personen', 'thema', 'ablauf'].includes(v.stil)) return stopp('FEHLER: Layout-ID oder Stil im Branding ungültig, keine Bilder erstellt.');
    varianten[pf][fm] = v;
  }
}
const titelFolie = folien[0];
const topic = String(paket.topic || titelFolie.heading || '').trim().slice(0, 120);
// Farben und Schriften im alten Zuschnitt bleiben für Knoten, die noch kunde lesen.
const bf = b.farben;
return [{ json: { bereit: true, kuerzel: e.kuerzel, paket_id: e.paket_id, trace_id: e.trace_id, test_fehler: e.test_fehler, paket: paket,
  kunde: { name: cust.name, farben: { primaer: bf.primaer, sekundaer: bf.sekundaer, akzent: bf.akzent, hintergrund: bf.hintergrund, text: bf.text }, schrift_titel: cust.schrift_titel, schrift_text: cust.schrift_text },
  customer: cust, branding_pack: b, branding_variants: varianten, branding_variant: varianten.instagram.karussell.id, platform: 'instagram', format: 'karussell',
  layout4_aktiv: LAYOUT4_AN || e.test_fehler === 'layout4' || e.test_fehler === 'l4fehler', slides: folien, topic: topic, thumbnail_hook: null, key_points: Array.isArray(paket.key_points) ? paket.key_points : [], process_steps: schritte, post_id: e.paket_id,
  branding_note: b.status === 'platzhalter' ? 'Platzhalter-Branding aus dem Kundenprofil, Austauschstellen im branding_pack.' : '',
  photo_query: String(paket.photo_query || '').trim().slice(0, 100) } }];

// Herkunft: Knoten "Foto auswerten" aus Projekt 1 (K1-Live-Export vom 19.11.2026), Code unveraendert bis auf den Knotennamen Branding waehlen. Per Skript uebernommen, nicht abgetippt.
// Auth-, Timeout- und Leerantworten fuehren sichtbar zum vorhandenen FLUX-Weg.
// Warum Pixabay (10.10.2026): Pexels stellt keine neuen API-Schluessel mehr aus. Treffer stehen in body.hits, das Bild in largeImageURL (hoechstens 1280 px).
const basis = $('Branding wählen [Code]').first().json;
// Warum alle Elemente (12.10.2026, Layout 4): Suchbegriffe bilden schickt bis zu 3 Suchanfragen, je Anfrage ein Element in derselben Reihenfolge.
const alle = $input.all();
const fragen = $('Suchbegriffe bilden [Code]').all().map(i => String(i.json.photo_query || ''));
// Warum der Suchbegriff geprueft wird: ohne q liefert Pixabay beliebte Bilder statt eines passenden Fotos.
const frage = String(basis.photo_query || '').trim();
// Warum Muster statt new URL: im Code-Knoten dieser Instanz verwarf new URL alle 5 echten Treffer (Hilfsaufruf 733). Das Muster laesst nur https://pixabay.com/ bzw. https://cdn.pixabay.com/ ohne Port und Zugangsdaten zu.
const safePhoto = s => typeof s === 'string' && /^https:\/\/(cdn\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const safeLink = s => typeof s === 'string' && /^https:\/\/(www\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
// Warum ganze Woerter (Fix 5a, 17.10.2026, Laeufe 1160, 1164, 1172): die alte Bewertung zaehlte Teilzeichenketten ("bot" in "bottle", "chat" in "chateau")
// und liess Bewertung 0 gewinnen, der erste Treffer der ersten Anfrage hatte Vorrang. Jetzt: Tags und Suchwoerter kleingeschrieben, an Satzzeichen
// getrennt, Plural grob auf die Einzahl gebracht (ies zu y, ches/shes/sses/xes ohne es, sonst ein s am Ende ab 4 Buchstaben, ss bleibt).
const einzahl = w => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : (/(ch|sh|ss|x)es$/.test(w) ? w.slice(0, -2) : (w.length >= 4 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w));
const FUELL = new Set(['a', 'an', 'the', 'of', 'with', 'and', 'or', 'for', 'on', 'in', 'at', 'to', 'by', 'from', 'into', 'over', 'under', 'near']);
const ALLGEMEIN = new Set(['people', 'person', 'technology', 'tech', 'innovation', 'innovative', 'digital', 'digitalization', 'automation', 'automated', 'business'].map(einzahl));
const woerterVon = s => String(s || '').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(einzahl);
// Warum abstrakte Woerter raus (Fix 5c, 17.10.2026, Lauf 1175): bei "error handling workflow" gewann eine Briefmarke nur ueber das Tag error.
// Abstrakte Woerter haben kein sichtbares Motiv. Gleiche Liste in Paket pruefen, Suchbegriffe bilden und Foto auswerten, Einzahl und Mehrzahl ueber einzahl.
// Erweitert: time saving, artificial intelligence, customer satisfaction kamen noch durch; dazu deutsche Woerter vom Ersatzweg, Umlaute als Unicode-Escape. Sie zaehlen weder als Suchwort noch als Treffer.
const ABSTRAKT = new Set(['error', 'failure', 'handling', 'workflow', 'process', 'management', 'solution', 'strategy', 'efficiency', 'optimization', 'system', 'data', 'information', 'concept', 'idea', 'success', 'growth', 'quality', 'problem', 'issue', 'integration', 'tool', 'service', 'feature', 'method', 'overview', 'guide', 'tip', 'step', 'setup', 'configuration', 'productivity', 'performance', 'benefit', 'challenge', 'future', 'time', 'saving', 'intelligence', 'artificial', 'satisfaction', 'experience', 'value', 'cost', 'result', 'goal', 'plan', 'planning', 'change', 'trend', 'skill', 'knowledge', 'learning', 'communication', 'collaboration', 'security', 'privacy', 'risk', 'insight', 'analysis', 'analytics', 'decision', 'efficient', 'optimize', 'opportunity', 'potential', 'approach', 'example', 'basic', 'introduction', 'tutorial', 'revenue', 'profit', 'marketing', 'transformation', 'trust', 'organization', 'impact', 'advantage', 'fehler', 'fehlerbehandlung', 'behandlung', 'ablauf', 'abläufe', 'prozess', 'prozesse', 'verwaltung', 'lösung', 'lösungen', 'loesung', 'loesungen', 'strategie', 'strategien', 'effizienz', 'systeme', 'daten', 'informationen', 'idee', 'ideen', 'erfolg', 'probleme', 'werkzeug', 'werkzeuge', 'einrichtung', 'konfiguration', 'automatisierung', 'zeitersparnis', 'ersparnis', 'zeit', 'sicherheit', 'datenschutz', 'optimierung', 'verbesserung', 'qualität', 'qualitaet', 'wachstum', 'zukunft', 'kosten', 'zufriedenheit', 'kundenzufriedenheit', 'künstliche', 'kuenstliche', 'intelligenz', 'anleitung', 'tipp', 'schritt', 'schritte', 'überblick', 'ueberblick', 'einführung', 'einfuehrung', 'grundlagen', 'analyse', 'entscheidung', 'planung', 'wissen', 'erfahrung', 'kommunikation', 'zusammenarbeit', 'risiko', 'vorteil', 'vorteile', 'herausforderung', 'ziel', 'ziele'].map(einzahl));
// Inhaltswoerter: ohne Fuellwoerter, allgemeine Ersatzbegriffe und abstrakte Woerter, mindestens 3 Zeichen oder mit Ziffer
const inhaltVon = s => Array.from(new Set(woerterVon(s).filter(w => !FUELL.has(w) && !ALLGEMEIN.has(w) && !ABSTRAKT.has(w) && (w.length >= 3 || /\d/.test(w)))));
// Warum immer 2: mit 1 Treffer genuegte in Lauf 1175 das Tag error. Anfragen unter 2 Inhaltswoertern werden uebersprungen.
const MINDEST = 2;
// Warum Ausschluss (12.10.2026, Laeufe 773 bis 775): keine Kinder, keine Maschinenteile und keine Tiere, solange das Thema sie nicht nennt.
// Warum englische Woerter dazu (Fix 5a): mit lang=en liefert Pixabay englische Tags, die deutschen Muster allein griffen dann nicht mehr.
const themaText = (String(basis.topic || '') + ' ' + frage).toLowerCase();
const KIND = /\b(kind|kinder|baby|babys|babies|kleinkind|mädchen|junge|schüler|schule|child|children|kid|kids|toddler|girl|girls|boy|boys|schoolchild|schoolchildren)\b/;
const TECHNIK = /\b(zahnrad|zahnräder|getriebe|mechanik|maschine|roboter|roboterarm|robotik|industrie|fabrik|motor|gear|gears|cogwheel|cogwheels|machine|machines|machinery|robot|robots|robotic|robotics|industry|industrial|factory|engine)\b/;
const TIER = /\b(vogel|tier|tiere|papagei|möwe|hund|katze|pferd|tierwelt|schnabel|bird|birds|animal|animals|parrot|seagull|gull|dog|dogs|puppy|cat|cats|kitten|horse|horses|wildlife|beak)\b/;
const technikOk = TECHNIK.test(themaText), tierOk = TIER.test(themaText);
let aussortiert = 0;
const verboten = h => { const t = String(h.tags || '').toLowerCase(); const v = KIND.test(t) || (!technikOk && TECHNIK.test(t)) || (!tierOk && TIER.test(t)); if (v) aussortiert++; return v; };
// Warum vergleichbar ueber alle Anfragen: jede Anfrage prueft die Mindestpassung gegen die eigenen Suchwoerter; gereiht wird nach Treffern gegen die
// Hauptanfrage (ihre Woerter umfassen die der Zusatzanfragen), dann nach Anteil der eigenen Suchwoerter, dann Anfrage-Reihenfolge, dann Pixabay-Reihenfolge.
const haupt = inhaltVon(fragen[0] || frage);
let geprueft = 0, gescheitert = 0, suchbar = 0, fehlerAnfragen = 0;
const passend = new Map();
alle.forEach((it, qi) => {
  const rr = (it && it.json) || {};
  const bb = rr.body || rr;
  const st = Number(rr.statusCode || 200);
  const eigene = inhaltVon(fragen[qi] || (qi === 0 ? frage : ''));
  // Warum vor der Fehlerpruefung (Fix 5c): eine Anfrage unter 2 Inhaltswoertern wird nicht ausgewertet, auch ihr Fehlschlag zaehlt nicht.
  if (eigene.length < MINDEST) return;
  suchbar++;
  // Warum eigene Zaehlung: photo_queries_failed zaehlt jede ausgewertete Anfrage mit Fehler oder HTTP-Status ausserhalb 200 bis 299, die Hauptanfrage eingeschlossen.
  if (rr.error || st < 200 || st >= 300) fehlerAnfragen++;
  if (rr.error || st < 200 || st >= 300 || !Array.isArray(bb.hits)) { gescheitert++; return; }
  bb.hits.forEach((h, pos) => {
    geprueft++;
    if (!h || !safePhoto(h.largeImageURL) || !safeLink(h.pageURL) || verboten(h)) return;
    const tags = new Set(woerterVon(h.tags));
    const treffer = eigene.filter(w => tags.has(w));
    if (treffer.length < MINDEST) return;
    const s = { h, qi, pos, n: treffer.length, anteil: treffer.length / eigene.length, nh: haupt.filter(w => tags.has(w)).length, woerter: treffer };
    const alt = passend.get(h.id);
    if (!alt || s.nh > alt.nh || (s.nh === alt.nh && s.anteil > alt.anteil)) passend.set(h.id, s);
  });
});
const rangliste = Array.from(passend.values()).sort((x, y) => y.nh - x.nh || y.anteil - x.anteil || x.qi - y.qi || x.pos - y.pos);
const best = frage && rangliste.length ? rangliste[0] : null;
const p = best ? best.h : null;
const ok = !!p;
// Kandidaten fuer Layout 4: nur Treffer mit Mindestpassung, in Rangfolge, ohne das Hauptfoto, hoechstens 8
const kandidaten = (frage ? rangliste.slice(1, 9) : []).map(x => ({url: x.h.largeImageURL, photo_id: x.h.id, user: String(x.h.user || ''), page: x.h.pageURL}));
// Warum Herkunft mitgeben: Pixabay verlangt, dass die Quelle sichtbar ist; Render-Liste bauen schreibt sie aufs Bild.
const nutzerUrl = ok && safeLink(p.userURL) ? p.userURL : '';
// Warum Praefix "Pixabay ohne nutzbaren Treffer" bleibt: Protokollzeile bauen ordnet den Hinweis an diesem Anfang ein; Render-Liste bauen reicht ihn als image_note bis zur Freigabe.
const kurz = String(frage).slice(0, 40);
// Warum eigener Hinweis ohne suchbare Anfrage (Fix 5c): dann gab es keine Fotosuche mit Inhalt, die Freigabe soll zeigen, dass der Begriff zu abstrakt war.
// Warum der Wortlaut: Foto suchen schickt bei leerem Suchbegriff trotzdem 1 Pixabay-Aufruf ohne Suchwort, seine Antwort wird nur nicht ausgewertet.
const ohneSuchwort = !fragen.some(s => s.trim());
const notiz = ok ? '' : (!suchbar ? 'Pixabay ohne nutzbaren Treffer (' + (kurz ? 'Suchbegriff "' + kurz + '"' : 'leerer Suchbegriff') + ' hat keine 2 konkreten Bildwörter, ' + (ohneSuchwort ? 'Pixabay-Aufruf ohne Suchwort nicht ausgewertet' : 'Pixabay-Antwort nicht ausgewertet') + '), weiter mit FLUX.'
  : gescheitert === suchbar ? 'Pixabay-Anfrage gescheitert, weiter mit FLUX.'
  : 'Pixabay ohne nutzbaren Treffer (kein passendes Schlagwort zu "' + kurz + '", ' + geprueft + ' Treffer geprüft' + (aussortiert ? ', ' + aussortiert + ' aussortiert' : '') + '), weiter mit FLUX.');
return [{json: {...basis, photo_ok: ok, photo_url: ok ? p.largeImageURL : '',
  photo_credit: ok ? {photographer: String(p.user || ''), photographer_url: nutzerUrl, source: 'Pixabay', pixabay_url: p.pageURL, photo_id: p.id} : null,
  photo_match: ok ? {query: fragen[best.qi] || frage, query_index: best.qi, words: best.woerter, main_hits: best.nh} : null,
  photo_candidates: kandidaten, photo_queries: fragen, photo_queries_failed: fehlerAnfragen, photo_filtered: aussortiert,
  photo_note: notiz}, pairedItem: {item: 0}}];

// Binäre Speichermodi über den n8n-Helper lesen, kein direkter Zugriff auf binary.data.
const basis = $('Foto auswerten [Code]').first().json;
const item = $input.first();
if (!item.binary?.foto) throw new Error('Foto-Download hat keine Binärdatei geliefert.');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'foto');
const jpeg = buffer.length > 3 && buffer[0] === 255 && buffer[1] === 216 && buffer[2] === 255;
const png = buffer.length > 8 && buffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
if ((!jpeg && !png) || buffer.length > 12 * 1024 * 1024) throw new Error('Foto ist kein JPEG/PNG oder größer als 12 MiB.');
return [{ json: { ...basis, photo_data_uri: 'data:' + (png ? 'image/png' : 'image/jpeg') + ';base64,' + buffer.toString('base64') }, pairedItem: { item: 0 } }];

// Zweck (Werkzeug 4, v02 B2a): je Folie und für das Einzelbild eine index.html im Kundenbranding bauen (Layouts hybrid, thema, ablauf aus Projekt 1, mit Logo und eingebetteten Schriften), Gotenberg macht daraus PNG 1080 x 1350.
