const ikon = d => '<svg width="46" height="46" viewBox="0 0 24 24" fill="none" stroke="' + c.p + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + d + '</svg>';
const ikonSpeichern = ikon('<path d="M6 3h12v18l-6-4-6 4z"/>');
const ikonHerz = ikon('<path d="M12 20s-7-4.4-9-8.6C1.6 8.2 3.6 5 6.8 5c2 0 3.4 1.1 4.2 2.4C11.8 6.1 13.2 5 15.2 5c3.2 0 5.2 3.2 3.8 6.4C19 15.6 12 20 12 20z"/>');
