const lumx = v => { const f = x => { x /= 255; return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4); }; return 0.2126 * f(v[0]) + 0.7152 * f(v[1]) + 0.0722 * f(v[2]); };
const kontrastx = (a, c) => { const x = lumx(a), y = lumx(c); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const grundRgb = rgb((plan.branding.farben || {}).grund_2) || rgb((plan.branding.farben || {}).grund_1) || [26, 26, 26];
const kiFarbe = ['#F5F7F6', '#ffffff', '#0f172a'].find(c => kontrastx(rgb(c), grundRgb) >= 4.5) || '#ffffff';
const KI_BADGE = '<div style="position:fixed;left:50%;bottom:34px;transform:translateX(-50%);z-index:99;white-space:nowrap;font:400 22px/1.2 IBM Plex Sans,DejaVu Sans,Arial,sans-serif;letter-spacing:.01em;color:' + kiFarbe + '">Mit KI erstellt</div>';
const seite = abfrage => {
  const p = JSON.parse(JSON.stringify(plan));
  p.fotos.forEach(f => { f.datei = b.fotos[parseInt(f.id.slice(1), 10) - 1]; });
  p.branding.logo.datei = p.branding.logo.datei ? b.logo : '';
  return b.kopf.replace('<!--PLAN-->', () => '<script type="application/json" id="plan">' + JSON.stringify(p).replace(/</g, '\\u003c') + '</script>')
    .replace('/*ABFRAGE*/', () => 'window.__ABFRAGE=' + JSON.stringify(abfrage) + ';')
    .replace('</body>', () => KI_BADGE + '</body>');
};
const ej = b.einzelbild_json || {};
const ordner = String(ej.path || '').replace(/\/[^\/]*$/, '');
if (!ordner) throw new Error('L4: Ablageordner aus dem Einzelbild nicht lesbar');
const zwei = z => String(z).padStart(2, '0');
const info = { layout: 'instagram_karussell_4', l4_fingerprint: 'L4:' + k.fingerprint, l4_kandidat: wahl + 1, l4_art: k.art, l4_versuch: k.versuch,
  l4_verworfen: verworfen, l4_hinweise: b.hinweise || [], l4_fotos: b.foto_zahl, l4_folien: plan.folien.length };
const hinweisL4 = [String(ej.bild_hinweis || ''), (b.hinweise || []).join('; ')].filter(Boolean).join('; ').slice(0, 280);
const aus = [];
for (let i = 1; i <= plan.folien.length; i++) {
  const html = seite('folie=' + i);
  const datei = 'folie-' + zwei(i) + '.png';
  const bin = await helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  aus.push({ json: Object.assign({ kind: 'folie', platform: 'instagram', format: 'karussell', branding_variant: 'instagram_karussell_4', index: i, file_name: datei, path: ordner + '/' + datei,
    paket_id: ej.paket_id, kuerzel: ej.kuerzel, bild_quelle: ej.bild_quelle, bild_hinweis: hinweisL4, ki_bild: ej.ki_bild, photo_credit: null, layout: 'layout4', ki_art: 'ki', ki_bildquelle: (i === 1 && kiId) ? 'flux' : '', html_chars: html.length }, info), binary: { index_html: bin }, pairedItem: { item: wahl } });
}
// Warum das Signal im Einzelbild: der Render-Knoten wartet bei allen Seiten auf data-fertig (waitForExpression)
const eh = String(b.einzelbild_html || '');
if (!eh.includes('</body>')) throw new Error('L4: Einzelbild-Seite ohne </body>');
const ebHtml = eh.replace('</body>', () => '<script>document.body.setAttribute("data-fertig","1")</script></body>');
const ebBin = await helpers.prepareBinaryData(Buffer.from(ebHtml, 'utf8'), 'index.html', 'text/html');
aus.push({ json: Object.assign({}, ej, info, { html_chars: ebHtml.length, bild_hinweis: hinweisL4 }), binary: { index_html: ebBin }, pairedItem: { item: wahl } });
return aus;

// Zweck (K2 B2b, aus Projekt 1): jedes Bild des Layout-4-Laufs pruefen (PNG, 1080 x 1350, Mindestgroesse). Fehlt eins oder ist es kaputt, geht der Lauf
// ueber den Fehlerausgang auf das bisherige Layout (Rueckfall altes Layout), nie mit halben Folien weiter.
const ein = $input.all();
const soll = $('Layout 4 Plan wählen [Code]').all().length;
if (ein.length !== soll) throw new Error('L4: ' + ein.length + ' von ' + soll + ' Bildern zurueck');
const PNG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
// Warum slide je Folie (12.10.2026): Post speichern legt die Texte des gerenderten Plans ab, nicht die des Pakets, damit Text und Bild je Folie zusammenpassen.
// Warum label: die sichtbare Marke (Schritt N, Fuer spaeter) gehoert zum gerenderten Text.
const rein = s => String(Array.isArray(s) ? s.join(' ') : (s || '')).replace(/\*/g, '').replace(/\s+/g, ' ').trim();
const pw = $('Layout 4 Plan wählen [Code]').first().json;
const plan = JSON.parse($('Layout 4 würfeln [Code]').all()[pw.l4_kandidat - 1].json.plan);
const slideVon = j => { if (j.kind !== 'folie') return {}; const f = plan.folien[j.index - 1] || {}; return { slide: { type: f.typ || '', heading: rein(f.titel || (f.typ === 'speichern' ? 'Jetzt speichern' : '')), text: rein(f.text || f.unter || (f.punkte || []).join(' | ')), label: rein(f.marke || '') } }; };
const aus = [];
for (let i = 0; i < ein.length; i++) {
  const it = ein[i];
  if (!it.binary || !it.binary.bild) throw new Error('L4: Bild ' + (i + 1) + ' ohne Datei (' + String((it.json.error && (it.json.error.message || it.json.error)) || 'Gotenberg ohne Bild').slice(0, 120) + ')');
  const buf = await this.helpers.getBinaryDataBuffer(i, 'bild');
  if (buf.length < 20000 || !buf.subarray(0, 8).equals(PNG)) throw new Error('L4: Bild ' + (i + 1) + ' ist kein PNG oder zu klein (' + buf.length + ' Byte)');
  const b = buf.readUInt32BE(16), h = buf.readUInt32BE(20);
  if (b !== 1080 || h !== 1350) throw new Error('L4: Bild ' + (i + 1) + ' hat ' + b + ' x ' + h + ' statt 1080 x 1350');
  aus.push({ json: Object.assign({}, it.json, { png_bytes: buf.length }, slideVon(it.json)), binary: { bild: it.binary.bild }, pairedItem: { item: i } });
}
return aus;

// Zweck (K2 B2b, aus Projekt 1): Rueckfall auf das bisherige Layout (Render-Liste bauen), wenn Layout 4 abgeschaltet ist oder Wuerfeln, Pruefen, Plan, Rendern oder Ergebnispruefung scheitert.
// Warum slide je Folie: Bilder pruefen baut daraus bilder.slides (flache Liste), damit der Einreichen-Sub die Texte genau so ablegt, wie sie auf den Bildern stehen. Gilt auch fuer diesen Rueckfall (ein Weg).
const f = ($input.first() || { json: {} }).json || {};
const e = f.error;
const grund = String((e && (e.message || e)) || f.message || 'unbekannt').replace(/\s+/g, ' ').slice(0, 220);
const aus = /LAYOUT4_AUS/.test(grund);
const note = aus ? '' : 'LAYOUT-4-RÜCKFALL: ' + grund.replace(/^L4:\s*/, '');
const alt = $('Render-Liste bauen [Code]').all();
if (!alt.length) throw new Error('Rueckfall ohne Render-Liste');
const pk = $('Branding wählen [Code]').first().json;
const folien = (pk.slides || []).map(x => ({ ...x }));
const slideVon = j => { if (j.kind !== 'folie') return {}; const x = folien[j.index - 1] || {}; return { slide: { type: x.type || 'inhalt', heading: String(x.heading || ''), text: String(x.text || '') } }; };
return alt.map(it => ({ json: Object.assign({}, it.json, { layout_note: note, bild_hinweis: [String(it.json.bild_hinweis || ''), note].filter(Boolean).join('; ').slice(0, 280) }, slideVon(it.json)), binary: it.binary, pairedItem: { item: 0 } }));

// Herkunft: Knoten "Suchbegriffe bilden" aus Projekt 1 (K1-Live-Export vom 19.11.2026), Code unveraendert bis auf den Knotennamen Branding waehlen. Per Skript uebernommen, nicht abgetippt.
// Zweck: bis zu 3 englische Suchbegriffe fuer Pixabay bilden, damit Layout 4 Fotos zu verschiedenen Schlagwoertern bekommt:
// (1) photo_query des Modells, (2) photo_query ohne das letzte Wort, (3) die zwei konkretesten Woerter von photo_query (mit Pixabay-Kategorie).
// Seit Fix 5c (17.10.2026): jede Anfrage hat mindestens 2 Inhaltswoerter, abstrakte Woerter zaehlen nicht und fallen aus dem Suchtext.
// Warum nur aus photo_query (Fix 5a, 17.10.2026, Laeufe 1160, 1164, 1172): die alte Heuristik nahm grossgeschriebene deutsche Hauptwoerter der Folien
// und das Thema; seit photo_query englisch ist und Foto suchen lang=en sendet, waeren deutsche Woerter Fehltreffer. key_points sind deutsch und lassen sich
// ohne Sprachmodell nicht uebersetzen, die Ableitung aus den key_points leistet deshalb das Modell in Regel 15.
// Warum die laengsten Woerter als "konkreteste": im Englischen sind kurze Woerter meist allgemein (app, man, work), laengere meist spezifisch
// (smartphone, barista, whiteboard). Fuellwoerter und allgemeine Ersatzbegriffe zaehlen nicht mit.
// Warum Kategorie nur bei Anfrage 3 (12.10.2026, Hilfsaufruf 792): business sortierte Tierfotos zu "Rechnung" aus; auf Anfrage 1 und 2 wuerde
// die Kategorie passende Fotos ausserhalb von business verdecken. food bei Gastro-Themen, jetzt mit englischen Woertern, weil photo_query englisch ist.
const basis = $('Branding wählen [Code]').first().json;
const q = String(basis.photo_query || '').replace(/\s+/g, ' ').trim();
const FUELL = new Set(['a', 'an', 'the', 'of', 'with', 'and', 'or', 'for', 'on', 'in', 'at', 'to', 'by', 'from', 'into', 'over', 'under', 'near']);
const einzahl = w => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : (/(ch|sh|ss|x)es$/.test(w) ? w.slice(0, -2) : (w.length >= 4 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w));
const ALLGEMEIN = new Set(['people', 'person', 'persons', 'technology', 'technologies', 'tech', 'innovation', 'innovative', 'digital', 'digitalization', 'automation', 'automated', 'business', 'businesses'].map(einzahl));
// Warum abstrakte Woerter raus (Fix 5c, 17.10.2026, Lauf 1175): bei "error handling workflow" gewann eine Briefmarke nur ueber das Tag error.
// Abstrakte Woerter haben kein sichtbares Motiv. Gleiche Liste in Paket pruefen, Suchbegriffe bilden und Foto auswerten, Einzahl und Mehrzahl ueber einzahl.
// Erweitert: time saving, artificial intelligence, customer satisfaction kamen noch durch; dazu deutsche Woerter vom Ersatzweg, Umlaute als Unicode-Escape.
const ABSTRAKT = new Set(['error', 'failure', 'handling', 'workflow', 'process', 'management', 'solution', 'strategy', 'efficiency', 'optimization', 'system', 'data', 'information', 'concept', 'idea', 'success', 'growth', 'quality', 'problem', 'issue', 'integration', 'tool', 'service', 'feature', 'method', 'overview', 'guide', 'tip', 'step', 'setup', 'configuration', 'productivity', 'performance', 'benefit', 'challenge', 'future', 'time', 'saving', 'intelligence', 'artificial', 'satisfaction', 'experience', 'value', 'cost', 'result', 'goal', 'plan', 'planning', 'change', 'trend', 'skill', 'knowledge', 'learning', 'communication', 'collaboration', 'security', 'privacy', 'risk', 'insight', 'analysis', 'analytics', 'decision', 'efficient', 'optimize', 'opportunity', 'potential', 'approach', 'example', 'basic', 'introduction', 'tutorial', 'revenue', 'profit', 'marketing', 'transformation', 'trust', 'organization', 'impact', 'advantage', 'fehler', 'fehlerbehandlung', 'behandlung', 'ablauf', 'abläufe', 'prozess', 'prozesse', 'verwaltung', 'lösung', 'lösungen', 'loesung', 'loesungen', 'strategie', 'strategien', 'effizienz', 'systeme', 'daten', 'informationen', 'idee', 'ideen', 'erfolg', 'probleme', 'werkzeug', 'werkzeuge', 'einrichtung', 'konfiguration', 'automatisierung', 'zeitersparnis', 'ersparnis', 'zeit', 'sicherheit', 'datenschutz', 'optimierung', 'verbesserung', 'qualität', 'qualitaet', 'wachstum', 'zukunft', 'kosten', 'zufriedenheit', 'kundenzufriedenheit', 'künstliche', 'kuenstliche', 'intelligenz', 'anleitung', 'tipp', 'schritt', 'schritte', 'überblick', 'ueberblick', 'einführung', 'einfuehrung', 'grundlagen', 'analyse', 'entscheidung', 'planung', 'wissen', 'erfahrung', 'kommunikation', 'zusammenarbeit', 'risiko', 'vorteil', 'vorteile', 'herausforderung', 'ziel', 'ziele'].map(einzahl));
// Warum dieselbe Wortzerlegung wie in Foto auswerten: eine Anfrage, die hier 2 Inhaltswoerter hat, muss dort ebenfalls 2 haben.
const woerterVon = s => String(s || '').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(einzahl);
const inhaltVon = s => Array.from(new Set(woerterVon(s).filter(w => !FUELL.has(w) && !ALLGEMEIN.has(w) && !ABSTRAKT.has(w) && (w.length >= 3 || /\d/.test(w)))));
// Warum mindestens 2: mit einem einzigen Wort fand Pixabay in Lauf 1175 ueber error eine Briefmarke.
const MINDEST = 2;
const thema = String(basis.topic || '');
const gastro = /(caf[eé]|kaffee|coffee|restaurant|b[äa]cker|bakery|k[üu]che|kitchen|essen|food|gastro|speise|kuchen|cake|bistro|bar\b)/i.test(thema + ' ' + q);
const kategorie = gastro ? 'food' : 'business';
// Abstrakte Woerter fallen auch aus dem Suchtext, sonst verlangt Pixabay sie als Pflichtwort
const woerter = q.split(' ').filter(Boolean).filter(t => { const teile = woerterVon(t); return !(teile.length && teile.every(w => ABSTRAKT.has(w))); });
const inhalt = woerter.map((w, i) => ({ w, i, k: w.toLowerCase().replace(/[^\p{L}\p{N}-]/gu, '') })).filter(x => inhaltVon(x.w).length);
const konkret = inhalt.slice().sort((a, b) => b.k.length - a.k.length || a.i - b.i).slice(0, 2).sort((a, b) => a.i - b.i).map(x => x.w).join(' ');
const liste = [];
const hat = s => liste.some(x => x.q.toLowerCase() === s.toLowerCase());
const add = (s, kat) => { s = String(s || '').trim(); if (s && inhaltVon(s).length >= MINDEST && !hat(s)) { liste.push({ q: s, kat }); return true; } return false; };
add(woerter.join(' '), '');
// Anfrage 2 ohne das letzte Wort; Fuellwoerter am Ende fallen mit weg
const ohneLetztes = woerter.slice(0, -1);
while (ohneLetztes.length && FUELL.has(ohneLetztes[ohneLetztes.length - 1].toLowerCase())) ohneLetztes.pop();
add(ohneLetztes.join(' '), '');
// Warum keine Einwort-Anfrage mehr (Fix 5c): ein Wort allein genuegte in Lauf 1175 fuer ein themenfremdes Foto. Doppelte entfallen ueber hat.
add(konkret, kategorie);
// Warum genau ein leeres Element, wenn nichts suchbar ist: bei 0 Elementen liefen Foto suchen und Foto auswerten gar nicht und der Ast endete.
// Foto suchen schickt dafuer 1 Pixabay-Aufruf ohne Suchwort; Foto auswerten wertet ihn nicht aus und schickt sichtbar zum FLUX-Weg.
if (!liste.length) liste.push({ q: '', kat: '' });
return liste.slice(0, 3).map((s, i) => ({ json: { ...basis, photo_query: s.q, photo_category: s.kat, photo_query_index: i }, pairedItem: { item: 0 } }));
